#include <bits/stdc++.h>
using namespace std;using U=uint64_t; using A=array<int,11>; using W=array<int,12>;
vector<int> cand; vector<int> TDs[72]; vector<array<int,2>> pairs; int pairid[12][12],triid[4096],group[12],w[12],goal[12],deg[12]; vector<int> p4[4096],p3[4096]; vector<int> tris; vector<int> lookup[66]; int bmask[495]; vector<U> bm,hm; vector<int> cb; vector<int> by[64],pure; U fullE,fullH; int chosen[11]; long long nodes=0,nsol=0,reps=0,tests=0,pass=0; bool stop=false; auto start=chrono::steady_clock::now();
set<A> sol; vector<array<int,12>> ps;
int pc(int x){return __builtin_popcount((unsigned)x);}
void tail(int i,int n,U h){if(n==11){if(h!=fullH)return;for(int x=0;x<12;x++)if(deg[x]!=goal[x])return;A a;for(int j=0;j<11;j++)a[j]=cb[chosen[j]];sort(a.begin(),a.end());sol.insert(a);return;}for(int k=i;k<(int)pure.size();k++){int j=pure[k];bool ok=true;int b=cb[j];for(int x=0;x<12;x++)if(b>>x&1 && deg[x]>=goal[x])ok=false;if(!ok)continue;for(int x=0;x<12;x++)if(b>>x&1)deg[x]++;chosen[n]=j;tail(k+1,n+1,h|hm[j]);for(int x=0;x<12;x++)if(b>>x&1)deg[x]--;}}
void dfs(U rem,U h,int n){if(stop)return;if((++nodes&262143)==0&&false){stop=true;return;}if(!rem){int need=0;for(int x=0;x<12;x++)need+=goal[x]-deg[x];if(need==4*(11-n))tail(0,n,h);return;}if(n>=11||__builtin_popcountll(rem)>6*(11-n))return;
vector<int> best;bool init=false;U t=rem;while(t){int i=__builtin_ctzll(t);t&=t-1;vector<int> opts;for(int j:by[i])if((bm[j]&rem)==bm[j]){bool ok=true;int b=cb[j];for(int x=0;x<12;x++)if(b>>x&1&&deg[x]>=goal[x]){ok=false;break;}if(ok)opts.push_back(j);}if(opts.empty())return;if(!init||opts.size()<best.size()){best=move(opts);init=true;if(best.size()==1)break;}}
for(int j:best){int b=cb[j];for(int x=0;x<12;x++)if(b>>x&1)deg[x]++;bool ok=true;for(int x=0;x<12;x++)if(goal[x]-deg[x]>10-n)ok=false;chosen[n]=j;if(ok)dfs(rem^bm[j],h|hm[j],n+1);for(int x=0;x<12;x++)if(b>>x&1)deg[x]--;if(stop)return;}}
void test(const A&a){ // all 72 x-links for a fixed normalized y-link; necessary residual incidence bound.
 bool c0[220]={};int p0[66]={};for(int i=0;i<66;i++)p0[i]=group[pairs[i][0]]==group[pairs[i][1]];for(int g=0;g<4;g++)c0[triid[7<<(3*g)]]=true;
 for(int b:a){for(int j:p3[b])c0[j]=true;for(int j:p4[b])p0[j]++;}
 for(auto &td:TDs){++tests;bool c[220];int p[66];copy(c0,c0+220,c);copy(p0,p0+66,p);for(int b:td){for(int j:p3[b])c[j]=true;for(int j:p4[b])p[j]++;}
 int h[66]={},v[12]={};for(int i=0;i<220;i++)if(!c[i]){int b=tris[i];for(int x=0;x<12;x++)if(b>>x&1)v[x]++;for(int j:p4[b])h[j]++;}
 int inc[12]={};for(int j=0;j<66;j++){int r=max(4-p[j],(h[j]+2)/3);for(int x:pairs[j])inc[x]+=r;}
 int total=0;for(int x=0;x<12;x++)total+=max({8-w[x],(v[x]+5)/6,(inc[x]+3)/4});if(total<=90){++pass; if(true){cout<<"survivor "<<total<<" weights";for(int x:w)cout<<' '<<x;cout<<" local";for(int b:a)cout<<' '<<b;cout<<" td";for(int b:td)cout<<' '<<b;cout<<'\n';}}
 }}
int main(){for(int i=0;i<12;i++){group[i]=i/3;for(int j=i+1;j<12;j++){pairid[i][j]=pairs.size();pairs.push_back({i,j});}}for(int b=0;b<4096;b++){if(pc(b)==3){triid[b]=tris.size();tris.push_back(b);}if(pc(b)==4)cand.push_back(b);for(int i=0;i<66;i++)if((b>>pairs[i][0]&1)&&(b>>pairs[i][1]&1))p4[b].push_back(i);}for(int b:cand)for(int t:tris)if((t&b)==t)p3[b].push_back(triid[t]);int nt,nl;cin>>nt>>nl;assert(nt==72);for(auto &td:TDs)for(int i=0,b;i<9;i++){cin>>b;td.push_back(b);}for(int l=0;l<nl;l++){for(int &x:w)cin>>x;for(int x=0;x<12;x++)goal[x]=3+w[x];fill(deg,deg+12,0);cb.clear();bm.clear();hm.clear();pure.clear();for(auto &v:by)v.clear();int ei[66],hi[66];fill(ei,ei+66,-1);fill(hi,hi+66,-1);int ne=0,nh=0;for(int j=0;j<66;j++){auto [x,y]=pairs[j];if(w[x]&&w[y]){if(group[x]!=group[y])hi[j]=nh++;}else if(group[x]!=group[y])ei[j]=ne++;}fullE=(1ULL<<ne)-1;fullH=(1ULL<<nh)-1;for(int b:cand){bool ok=true;U e=0,h=0;for(int j:p4[b]){auto[x,y]=pairs[j];if(group[x]==group[y]&&(!w[x]||!w[y])){ok=false;break;}if(ei[j]>=0)e|=1ULL<<ei[j];if(hi[j]>=0)h|=1ULL<<hi[j];}if(!ok)continue;int j=cb.size();cb.push_back(b);bm.push_back(e);hm.push_back(h);if(!e)pure.push_back(j);while(e){int i=__builtin_ctzll(e);e&=e-1;by[i].push_back(j);}}
 sol.clear();dfs(fullE,0,0);if(stop){cout<<"TIME_LIMIT layout "<<l<<" partial local solutions "<<sol.size()<<'\n';break;}nsol+=sol.size();if(sol.empty())continue;
 // All within/between-group permutations preserving weight labels. Collapse complete local solutions by this group.
 ps.clear();array<int,4> gp={0,1,2,3};do{vector<array<int,3>> v[4];bool ok=true;for(int i=0;i<4;i++){array<int,3> t={3*gp[i],3*gp[i]+1,3*gp[i]+2};do{bool match=true;for(int k=0;k<3;k++)if(w[3*i+k]!=w[t[k]])match=false;if(match)v[i].push_back(t);}while(next_permutation(t.begin(),t.end()));if(v[i].empty())ok=false;}if(!ok)continue;for(auto a:v[0])for(auto b:v[1])for(auto c:v[2])for(auto d:v[3])ps.push_back({a[0],a[1],a[2],b[0],b[1],b[2],c[0],c[1],c[2],d[0],d[1],d[2]});}while(next_permutation(gp.begin(),gp.end()));
 int count=0;while(!sol.empty()){A a=*sol.begin();++reps;++count;set<A> orbit;for(auto p:ps){A z;for(int j=0;j<11;j++){int b=a[j],m=0;for(int i=0;i<12;i++)if(b>>i&1)m|=1<<p[i];z[j]=m;}sort(z.begin(),z.end());orbit.insert(z);}for(auto z:orbit){assert(sol.count(z));sol.erase(z);}test(a);}cout<<"layout "<<l<<" representatives "<<count<<" tests so far "<<tests<<" survivors "<<pass<<'\n';
 }cout<<"FINAL "<<(stop?"TIME_LIMIT":"EXHAUSTED")<<" nodes "<<nodes<<" local "<<nsol<<" reps "<<reps<<" tests "<<tests<<" survivors "<<pass<<'\n';}
